
const state={user:null,page:localStorage.getItem('PMA_CURRENT_PAGE')||'home',market:localStorage.getItem('PMA_MARKET')||'Forex',symbol:localStorage.getItem('PMA_SYMBOL')||'EURUSD',ref:new URLSearchParams(location.search).get('ref')||'',notif:[],scannerTimer:null,entryTimer:null,dayTradeTimer:null,notifTimer:null,restoringReload:false};
const markets={Forex:['EURUSD','GBPUSD','USDJPY','GBPJPY','AUDUSD','USDCAD','USDCHF','NZDUSD','EURJPY','EURGBP','EURCHF','GBPCHF','AUDJPY','CADJPY'],Indices:['US30','NAS100','SPX500','GER40','UK100','FRA40','JP225'],Metals:['XAUUSD','XAGUSD','XPTUSD','XPDUSD'],Crypto:['BTCUSD','ETHUSD','SOLUSD','XRPUSD','LTCUSD'],Commodities:['USOIL','UKOIL','NATGAS','COPPER']};
const API_BASE=(localStorage.getItem('PMA_API_BASE')||'https://pips-master-frontend.onrender.com').replace(/\/$/,'');
function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const token=localStorage.getItem('PMA_TOKEN');if(token)headers.Authorization='Bearer '+token;return fetch(API_BASE+'/api'+path,{...opts,headers}).then(async r=>{const x=await r.json().catch(()=>({}));if(!r.ok)throw Error(x.detail||'Request failed');return x})}
function show(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id).classList.add('active');if(id==='signup'&&state.ref){suMsg.textContent='Referral code: '+state.ref;suMsg.className='form-msg ok'}if(id==='app')page(state.page||'home',true)}
function togglePassword(id,btn){const el=document.getElementById(id);el.type=el.type==='password'?'text':'password';btn.textContent=el.type==='password'?'👁️':'🙈'}
function validateSignup(){if(!document.getElementById('suPass'))return;const p=suPass.value,p2=suPass2.value;suPassMsg.textContent=p.length===0?'':'Password must be at least 8 characters.';suPassMsg.className='form-msg '+(p.length>=8?'ok':'error');suMatchMsg.textContent=p2.length===0?'':(p===p2?'Passwords match.':'Passwords do not match.');suMatchMsg.className='form-msg '+(p2.length===0?'':(p===p2?'ok':'error'))}
function saveLocalUser(u){localStorage.setItem('PMA_LOCAL_USER',JSON.stringify(u));state.user=u;localStorage.setItem('PMA_USER_PROFILE',JSON.stringify(u))}
function addNotification(title,text,type='info'){const arr=JSON.parse(localStorage.getItem('PMA_NOTIFICATIONS')||'[]');arr.unshift({id:Date.now()+Math.random(),title,text,type,time:new Date().toLocaleString(),read:false});localStorage.setItem('PMA_NOTIFICATIONS',JSON.stringify(arr.slice(0,60)));state.notif=arr;updateNotifBadge()}
function getNotifications(){try{return JSON.parse(localStorage.getItem('PMA_NOTIFICATIONS')||'[]')}catch{return []}}
function updateNotifBadge(){const n=getNotifications();const unread=n.filter(x=>!x.read).length;const b=document.getElementById('notifBadge');if(b)b.textContent=String(unread)}
function loadLocalUser(){try{return JSON.parse(localStorage.getItem('PMA_LOCAL_USER')||'null')}catch{return null}}
async function signup(){validateSignup();if(!suUser.value.trim()||!suName.value.trim()||!suEmail.value.trim()){suMsg.textContent='Please complete all required fields.';suMsg.className='form-msg error';return}if(suPass.value.length<8||suPass.value!==suPass2.value){suMsg.textContent=suPass.value!==suPass2.value?'Passwords do not match.':'Please fix the password above.';suMsg.className='form-msg error';return}const email=suEmail.value.trim().toLowerCase();try{const x=await api('/auth/signup',{method:'POST',body:JSON.stringify({username:suUser.value,full_name:suName.value,email,password:suPass.value,confirm_password:suPass2.value,referral:state.ref})});state.user=x.user;localStorage.setItem('PMA_TOKEN',x.token||'');saveLocalUser(x.user);addNotification('Welcome to Pips Master Academy','Your account was created successfully.');enterApp(true)}catch(e){const u={username:suUser.value.trim(),full_name:suName.value.trim(),email,password:suPass.value,role:'user',pma_id:'PMA-'+Math.floor(100000+Math.random()*900000),referral_code:'PMA'+Math.floor(100000+Math.random()*900000),profile_picture:''};saveLocalUser(u);addNotification('Welcome to Pips Master Academy','Your local account is ready.');enterApp(true);toast('Account created in local mode. Connect your backend for multi-device accounts.')}}
async function login(){const email=liEmail.value.trim().toLowerCase(),pass=liPass.value;try{const x=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password:pass})});state.user=x.user;localStorage.setItem('PMA_TOKEN',x.token||'');saveLocalUser(x.user);addNotification('Welcome back','You successfully logged in.');enterApp(true);return}catch(e){}const local=loadLocalUser();if(local&&local.email.toLowerCase()===email&&local.password===pass){state.user=local;enterApp(true);return}liMsg.textContent='Login failed. Check your email and password.';liMsg.className='form-msg error'}
function enterApp(resetPage=false){show('app');adminNav.classList.toggle('hidden',state.user?.role!=='admin');userMini.textContent='@'+state.user.username;if(resetPage){state.page='home';localStorage.setItem('PMA_CURRENT_PAGE','home');localStorage.removeItem('PMA_SCROLL_HOME')}page(state.page||'home',!resetPage)}
function closeMenu(){document.getElementById('side').classList.remove('open')}
function page(p,restore=false){if(state.page&&state.page!==p){const old=document.getElementById('screen');if(old)localStorage.setItem('PMA_SCROLL_'+state.page,String(old.scrollTop||0))}state.page=p;localStorage.setItem('PMA_CURRENT_PAGE',p);localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol);closeMenu();pageTitle.textContent=p==='profile'?'My Profile':p[0].toUpperCase()+p.slice(1);const s=document.getElementById('screen');const views={home,signals,daytrade,calculator,progress,referrals,community,profile,about,admin};s.innerHTML=(views[p]||home)();if(p==='calculator')setCalcTab('risk');if(state.page!=='signals')clearInterval(state.scannerTimer);if(state.page!=='daytrade')clearInterval(state.dayTradeTimer);if(p==='signals')startScanner();if(p==='daytrade')startDayTrade();if(p==='progress')loadProgress();if(p==='referrals')loadReferrals();if(p==='community')loadMessages();if(p==='admin')loadAdminStats();requestAnimationFrame(()=>{s.scrollTop=restore?Number(localStorage.getItem('PMA_SCROLL_'+p)||0):0})}
function home(){return `<div class="section"><div class="home-hero"><div class="card"><div class="pill">PIPS MASTER ACADEMY</div><h1 class="section-title" style="font-size:46px;margin-top:18px">A complete space for the modern learner.</h1><p class="lead">Learn market structure, explore opportunities, manage risk and stay connected with a community built around disciplined decision-making.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="btn" onclick="page('signals')">Explore Signals</button><button class="btn alt" onclick="page('about')">Explore Academy</button></div><div class="divider"></div><div class="statline"><span>Personal PMA ID</span><b>${state.user.pma_id}</b></div><div class="statline"><span>Account role</span><b>${state.user.role==='admin'?'Administrator':'Member'}</b></div></div><img class="home-hero-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85" alt="Global financial markets"></div><div class="photo-section"><div class="photo-grid"><article class="card photo-card"><img src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1400&q=85" alt="Trader analysing financial markets"><div class="photo-overlay"><h3>See the market, not just the numbers.</h3><p class="muted" style="margin:0">A more visual workspace for charts, market structure and disciplined planning.</p></div></article><article class="card photo-card"><img src="https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&w=1000&q=85" alt="Financial market workspace"><div class="photo-overlay"><h3>Built around real market context.</h3><p class="muted" style="margin:0">Explore different market categories and live chart views.</p></div></article></div><div class="photo-grid-small"><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=900&q=85" alt="Market analysis screen"><h3 style="margin:12px 0 6px">Analysis</h3><p class="muted">Charts and structure in one place.</p></article><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=900&q=85" alt="Planning and finance workspace"><h3 style="margin:12px 0 6px">Planning</h3><p class="muted">Think through the setup before acting.</p></article><article class="card"><img class="real-photo" src="https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=900&q=85" alt="Professional workspace"><h3 style="margin:12px 0 6px">Professional feel</h3><p class="muted">A cleaner, more mature academy experience.</p></article></div><div class="image-band"><img src="https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=85" alt="Professional team workspace"><img src="https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=900&q=85" alt="Team collaboration"><img src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=85" alt="Learning with technology"><img src="https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=900&q=85" alt="Business meeting"></div></div><div class="feature-grid"><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=1200&q=85" alt="Candlestick analysis"><h3>Market structure</h3><p class="muted">Study trends, support and resistance, supply and demand, momentum and confirmation in one organised workspace.</p></div><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&w=1200&q=85" alt="Trading dashboard"><h3>Opportunity scanning</h3><p class="muted">Select a market category and search symbols instead of being limited to a tiny fixed watchlist.</p></div><div class="card"><img class="feature-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85" alt="Financial chart"><h3>Risk first</h3><p class="muted">Use the calculator to understand risk before acting. A good process starts before an entry.</p></div></div><div class="split"><div class="card"><h2>Built for clarity</h2><p class="lead">The academy keeps important information in focused sections instead of putting everything into one crowded page. Your profile, signals, calculator, community and learning material each have their own workspace.</p><p class="muted">The website is designed to grow as more market-data, learning and community services are connected.</p></div><div class="card"><img class="mini-img" src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=85" alt="Trader workspace"><h3 style="margin-top:15px">One workspace. More structure.</h3><p class="muted">Follow your own learning process, keep your account information organised and explore market tools without unnecessary clutter.</p></div></div><div class="grid" style="margin-top:18px"><div class="card"><div class="muted">Market categories</div><div class="big">${Object.keys(markets).length}</div><p class="muted">Forex, indices, metals, crypto and commodities.</p></div><div class="card"><div class="muted">Searchable symbols</div><div class="big">${Object.values(markets).flat().length}+</div><p class="muted">Expandable as your data provider grows.</p></div><div class="card"><div class="muted">Community</div><div class="big">Live</div><p class="muted">Group conversation and official updates.</p></div><div class="card"><div class="muted">Profile control</div><div class="big">Editable</div><p class="muted">Personal details can be updated while account IDs remain protected.</p></div></div><div class="footer-note">Pips Master Academy • Learn first. Analyse clearly. Manage risk responsibly.</div></div>`}
function signals(){return `<div class="section"><h1 class="section-title">Automated Market Scanner</h1><p class="lead">Live verified candle data is analysed across 15m, 30m, 1h, 4h and 1D. The engine shows the current directional setup, projected zones and the next confirmation condition.</p><div class="filters"><button class="btn alt" onclick="scanMarket()">↻ Refresh</button><button class="btn ghost" onclick="page('daytrade')">Open Day Trade</button></div><span id="scannerStatus" class="muted" style="display:block;margin-top:8px;font-size:12px">Connecting to verified market data…</span><div class="card"><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';state.symbol='';page('signals')">${x}</button>`).join('')}</div><div class="filters"><input id="symbolSearch" class="search" placeholder="Search a supported symbol, e.g. EURUSD, GBPUSD, XAUUSD" oninput="renderScanner()"><button class="btn alt" onclick="clearSymbolSearch()">Clear</button></div><div id="symbolResults" class="chips"></div></div><div class="card trend-panel"><h3>Multi-timeframe trend</h3><p class="muted">Each timeframe is calculated independently from the verified candle feed.</p><div id="trendGrid" class="trend-grid"></div></div><div class="card tv-wrap"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><b>TradingView Live Chart</b><div class="muted" id="tvSymbolLabel">${state.symbol||markets[state.market][0]}</div></div><span class="pill">15m</span></div><iframe id="tvFrame" title="TradingView chart" allowtransparency="true" scrolling="no"></iframe></div><div id="scannerArea"></div><div class="card" style="margin-top:16px"><h3>Closest monitored setups</h3><p class="muted">These are ranked by setup state and estimated travel to the next opposing zone.</p><div id="nearbySetups"></div></div></div>`}
function fmtDuration(mins){if(mins==null)return '—';const m=Math.max(0,Math.round(mins));if(m<60)return m+' min';const h=Math.floor(m/60),r=m%60;return h+'h'+(r?' '+r+'m':'')}
function formatEntryEta(c){return c?.candles_to_next_zone!=null?`≈ ${c.candles_to_next_zone} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)}`:'Waiting for verified data…'}
function startScanner(){clearInterval(state.scannerTimer);renderScanner();scanMarket();state.scannerTimer=setInterval(scanMarket,30000)}
function clearSymbolSearch(){const el=document.getElementById('symbolSearch');if(el)el.value='';renderScanner()}
function renderScanner(){const area=document.getElementById('scannerArea');if(!area)return;const q=(document.getElementById('symbolSearch')?.value||'').toUpperCase();const syms=markets[state.market].filter(x=>x.includes(q));document.getElementById('symbolResults').innerHTML=syms.map(x=>`<button class="chip ${state.symbol===x?'active':''}" onclick="state.symbol='${x}';renderScanner()">${x}</button>`).join('')||'<span class="muted">No matching supported symbol.</span>';const selected=state.symbol||syms[0]||markets[state.market][0];updateTradingView(selected);area.innerHTML=`<div class="card closest signal"><div class="pill">● PMA AUTOMATED SIGNAL ENGINE</div><div class="scanner-heading"><div><h2 id="selectedSymbol">${selected}</h2><div class="muted">${state.market}</div></div><div id="selectedDirection" class="signal-badge">WAITING</div></div><div id="selectedEta" class="eta">Connecting to verified market data…</div><p id="selectedZone" class="muted">Analysing trend, structure, supply/demand and support/resistance.</p><div id="selectedMeta" class="zone-badge">Verified data only</div><div id="selectedStats" class="scanner-stats"></div><div id="selectedDetails" class="scanner-details"></div></div>`;renderTrendGrid();scanMarket()}
function updateTradingView(symbol){const frame=document.getElementById('tvFrame');if(!frame)return;const tv=state.market==='Forex'?'FX:'+symbol:(state.market==='Indices'?'CAPITALCOM:'+symbol:(state.market==='Metals'?'OANDA:'+symbol:(state.market==='Crypto'?'COINBASE:'+symbol:'TVC:'+symbol)));document.getElementById('tvSymbolLabel').textContent=symbol;frame.src='https://www.tradingview.com/widgetembed/?symbol='+encodeURIComponent(tv)+'&interval=15&hidesidetoolbar=1&symboledit=1&saveimage=0&toolbarbg=%23081118&hideideas=1&theme=dark&style=1&timezone=Etc%2FUTC'}
async function scanMarket(){const selected=state.symbol||markets[state.market][0];try{const scanSymbols=[selected,...markets[state.market].filter(x=>x!==selected).slice(0,7)].join(',');const q=await api('/signals/scan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(scanSymbols));const c=(q.opportunities||[]).find(x=>x.symbol===selected)||q.closest;const statusEl=document.getElementById('scannerStatus');if(statusEl)statusEl.textContent=q.message||'Verified market data loaded.';if(!c){document.getElementById('selectedEta').textContent='NO VERIFIED MARKET DATA';document.getElementById('selectedZone').textContent=q.message||'No verified candle response.';document.getElementById('selectedMeta').textContent='No verified candle response • no signal generated';document.getElementById('selectedStats').innerHTML='';document.getElementById('selectedDetails').innerHTML='';const dir=document.getElementById('selectedDirection');if(dir)dir.textContent='NO DATA';renderTrendGrid({});renderNearby([]);return}const dir=document.getElementById('selectedDirection');if(dir)dir.textContent=c.direction||'NO TRADE';document.getElementById('selectedEta').textContent=formatEntryEta(c);document.getElementById('selectedZone').textContent=c.next_zone!=null?`${c.direction} • next ${c.zone_type||'zone'} at ${c.next_zone} • ${c.pips_to_next_zone??'—'} pips away`:'Waiting for the next qualifying zone.';document.getElementById('selectedMeta').textContent=`${c.candles_to_next_zone??'—'} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)} • ${c.status||'WATCHING'} • updated ${new Date(c.updated_at).toLocaleTimeString()}`;document.getElementById('selectedStats').innerHTML='<span><b>'+((c.setup_strength??'—'))+'/100</b> setup strength</span><span><b>'+((c.trend_alignment||'—'))+'</b> trend alignment</span><span><b>'+((c.validation?.win_rate??'—'))+(c.validation?.win_rate!=null?'%':'')+'</b> historical validation</span><span><b>'+((c.validation?.samples??0))+'</b> samples</span>';document.getElementById('selectedDetails').innerHTML=`<div class="detail-grid"><div><small>Entry zone</small><b>${c.entry_zone??'—'}</b></div><div><small>Stop loss</small><b>${c.stop_loss??'—'}</b></div><div><small>TP1</small><b>${c.take_profit_1??'—'}</b></div><div><small>TP2</small><b>${c.take_profit_2??'—'}</b></div><div><small>Structure</small><b>${escapeHtml(c.structure||'—')}</b></div><div><small>Next signal</small><b>${escapeHtml(c.next_signal_status||'—')}</b></div><div><small>Trigger</small><b>${escapeHtml(c.next_signal_trigger||'—')}</b></div><div><small>RSI 15m</small><b>${c.rsi_15m??'—'}</b></div><div><small>Support</small><b>${c.support??'—'}</b></div><div><small>Resistance</small><b>${c.resistance??'—'}</b></div></div><div class="notice" style="margin-top:12px"><b>Why this setup:</b> ${escapeHtml((c.reasons||[]).join(' • ')||'Waiting for more confluence.')}</div>`;renderTrendGrid(c.trends||{});renderNearby(q.opportunities||[]);const key='PMA_LAST_SIGNAL_'+selected;const previous=localStorage.getItem(key);if(c.status==='SIGNAL READY'&&previous!==String(c.updated_at||'')){addNotification('New scanner setup',`${selected} has a ${c.direction} setup ready for confirmation.`,'signal');localStorage.setItem(key,String(c.updated_at||''))}}catch(e){const statusEl=document.getElementById('scannerStatus');if(statusEl)statusEl.textContent='Scanner error: '+(e?.message||'unknown error');document.getElementById('selectedEta').textContent='NO VERIFIED MARKET DATA';document.getElementById('selectedZone').textContent='Live feed error: '+(e?.message||'unknown error');document.getElementById('selectedMeta').textContent='Verified feed unavailable • no signal generated';document.getElementById('selectedStats').innerHTML='';document.getElementById('selectedDetails').innerHTML='';renderTrendGrid({});renderNearby([])}}
function renderTrendGrid(trends={}){const el=document.getElementById('trendGrid');if(!el)return;const frames=[['15m','15 Minutes'],['30m','30 Minutes'],['1h','1 Hour'],['4h','4 Hours'],['1d','1 Day']];el.innerHTML=frames.map(([key,label])=>{const v=trends[key];const ok=['Bullish','Bearish','Neutral'].includes(v);return `<div class="trend-box"><span>${label}</span><strong>${ok?v:'Feed unavailable'}</strong><small>${ok?'Verified candle analysis':'No verified candle response'}</small></div>`}).join('')}
function renderNearby(items){const el=document.getElementById('nearbySetups');if(!el)return;if(!items.length){el.innerHTML='<p class="muted">No verified setups are available yet.</p>';return}el.innerHTML=items.slice(0,8).map(x=>`<div class="near-row"><div><div class="near-symbol">${x.symbol} • ${x.direction||'NO TRADE'}</div><div class="muted">${x.status||'WATCHING'} • next ${x.next_zone_type||'zone'} • ${x.pips_to_next_zone??'—'} pips • ${x.candles_to_next_zone??'—'} candles</div></div><div class="near-eta">${formatEntryEta(x)}</div></div>`).join('')}
function notifyNear(symbol,detail){if(window.Notification&&Notification.permission==='granted')new Notification('Pips Master Academy',{body:symbol+' is approaching its '+detail+' zone.'});toast(symbol+' is approaching its '+detail+' zone')}

function calculator(){return `<div class="section"><h1 class="section-title">Trading Calculator Hub</h1><p class="lead">Use the tools below with your own numbers. Broker specifications can differ, so treat results as estimates.</p><div class="calc-tabs"><button class="chip active" data-calc="risk" onclick="setCalcTab('risk')">Risk</button><button class="chip" data-calc="pnl" onclick="setCalcTab('pnl')">Profit / Loss</button><button class="chip" data-calc="pip" onclick="setCalcTab('pip')">Pip Value</button><button class="chip" data-calc="rr" onclick="setCalcTab('rr')">R:R</button><button class="chip" data-calc="margin" onclick="setCalcTab('margin')">Margin</button><button class="chip" data-calc="compound" onclick="setCalcTab('compound')">Compounding</button></div><div id="calcPanel" class="card"></div><div class="grid3" style="margin-top:18px"><div class="card"><h3>Risk</h3><p class="muted">Understand your planned risk before using an entry idea.</p></div><div class="card"><h3>Position size</h3><p class="muted">Position size depends on your stop distance and instrument value.</p></div><div class="card"><h3>Planning</h3><p class="muted">Use the calculator alongside the scanner instead of treating a signal as a guarantee.</p></div></div></div>`}
function setCalcTab(tab){document.querySelectorAll('[data-calc]').forEach(b=>b.classList.toggle('active',b.dataset.calc===tab));const panel=document.getElementById('calcPanel');if(!panel)return;const forms={risk:`<div class="grid"><div class="field"><label>Balance</label><input id="cBal" type="number" value="1000"></div><div class="field"><label>Risk %</label><input id="cRisk" type="number" value="1" step="0.1"></div><div class="field"><label>Stop distance (pips/points)</label><input id="cStop" type="number" value="20"></div><div class="field"><label>Value per pip/point per lot</label><input id="cPipVal" type="number" value="10"></div></div><button class="btn" onclick="runCalc('risk')">Calculate</button>`,pnl:`<div class="grid"><div class="field"><label>Entry</label><input id="pEntry" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Exit</label><input id="pExit" type="number" value="1.1050" step="0.0001"></div><div class="field"><label>Lot size</label><input id="pLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="pPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pnl')">Calculate</button>`,pip:`<div class="grid"><div class="field"><label>Lot size</label><input id="vLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="vPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pip')">Calculate</button>`,rr:`<div class="grid"><div class="field"><label>Entry</label><input id="rEntry" type="number" value="100"></div><div class="field"><label>Stop loss</label><input id="rSl" type="number" value="95"></div><div class="field"><label>Take profit</label><input id="rTp" type="number" value="110"></div></div><button class="btn" onclick="runCalc('rr')">Calculate</button>`,margin:`<div class="grid"><div class="field"><label>Units / contract size</label><input id="mUnits" type="number" value="100000"></div><div class="field"><label>Price</label><input id="mPrice" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Leverage</label><input id="mLev" type="number" value="100"></div></div><button class="btn" onclick="runCalc('margin')">Calculate</button>`,compound:`<div class="grid"><div class="field"><label>Starting balance</label><input id="coStart" type="number" value="1000"></div><div class="field"><label>Return per period %</label><input id="coRate" type="number" value="2" step="0.1"></div><div class="field"><label>Number of periods</label><input id="coPeriods" type="number" value="12"></div></div><button class="btn" onclick="runCalc('compound')">Calculate</button>`};panel.innerHTML=forms[tab]+'<div id="calcResult" style="margin-top:18px"></div>'}
function runCalc(kind){const out=document.getElementById('calcResult');if(!out)return;let html='';if(kind==='risk'){const risk=+cBal.value*(+cRisk.value/100),lot=risk/(Math.max(+cStop.value,1e-9)*Math.max(+cPipVal.value,1e-9));html=`<div class="notice">Risk amount: <b>${risk.toFixed(2)}</b><br>Estimated position size: <b>${lot.toFixed(3)}</b> lots`;}else if(kind==='pnl'){const pips=Math.abs(+pExit.value-+pEntry.value);const pnl=pips*(+pLot.value)*(+pPip.value);html=`<div class="notice">Price distance: <b>${pips.toFixed(5)}</b><br>Estimated P/L: <b>${pnl.toFixed(2)}</b> in the value unit you entered.`;}else if(kind==='pip'){const val=(+vLot.value)*(+vPip.value);html=`<div class="notice">Estimated pip/point value: <b>${val.toFixed(2)}</b>`;}else if(kind==='rr'){const risk=Math.abs(+rEntry.value-+rSl.value),reward=Math.abs(+rTp.value-+rEntry.value);html=`<div class="notice">Risk distance: <b>${risk.toFixed(5)}</b><br>Reward distance: <b>${reward.toFixed(5)}</b><br>Risk-to-reward: <b>1 : ${reward/Math.max(risk,1e-9).toFixed(2)}</b>`;}else if(kind==='margin'){const margin=(+mUnits.value*+mPrice.value)/Math.max(+mLev.value,1);html=`<div class="notice">Estimated margin: <b>${margin.toFixed(2)}</b><br><span class="muted">Actual margin depends on the broker and instrument contract rules.</span>`;}else{const projected=+coStart.value*Math.pow(1+(+coRate.value/100),Math.max(0,+coPeriods.value));html=`<div class="notice">Illustrative projected balance: <b>${projected.toFixed(2)}</b><br><span class="muted">This is a mathematical projection, not a promise of returns.</span>`;}out.innerHTML=html+'</div>'}
function daytrade(){return `<div class="section"><h1 class="section-title">Day Trade Monitor</h1><p class="lead">A daily watchlist using 15m trigger conditions with 1h and 4h context. It does not place orders.</p><div class="card"><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';page('daytrade')">${x}</button>`).join('')}</div><button class="btn alt" onclick="loadDayTrade()">↻ Refresh day-trade setups</button><span id="dayTradeStatus" class="muted" style="display:block;margin-top:8px">Loading verified day-trade data…</span></div><div id="dayTradeArea" class="grid3" style="margin-top:18px"></div></div>`}
function startDayTrade(){clearInterval(state.dayTradeTimer);loadDayTrade();state.dayTradeTimer=setInterval(loadDayTrade,60000)}
async function loadDayTrade(){const area=document.getElementById('dayTradeArea');if(!area)return;try{const symbols=markets[state.market].slice(0,8).join(',');const x=await api('/day-trade/plan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(symbols));document.getElementById('dayTradeStatus').textContent='Verified day-trade data updated: '+new Date(x.updated_at).toLocaleTimeString();area.innerHTML=(x.setups||[]).map(s=>`<article class="card day-card"><div class="pill">${s.day_trade_state||'WAITING'}</div><h2>${s.symbol}</h2><div class="big">${s.direction||'NO TRADE'}</div><p class="muted">Strength ${s.setup_strength??'—'}/100 • ${s.trend_alignment||'—'} trend alignment</p><div class="statline"><span>Entry zone</span><b>${s.entry_zone??'—'}</b></div><div class="statline"><span>Next zone</span><b>${s.next_zone??'—'}</b></div><div class="statline"><span>ETA</span><b>${formatEntryEta(s)}</b></div><div class="statline"><span>Next signal</span><b>${s.next_signal_status||'—'}</b></div><p class="muted">${escapeHtml(s.day_trade_reason||'')}</p></article>`).join('')||'<div class="notice">No verified day-trade setups returned yet.</div>';}catch(e){const st=document.getElementById('dayTradeStatus');if(st)st.textContent='Day-trade feed unavailable: '+(e?.message||'unknown error');area.innerHTML='<div class="notice">No verified day-trade data is available right now.</div>'}}
function progress(){return `<div class="section"><h1 class="section-title">My Progress</h1><p class="lead">Your academy progress is stored with your account. Rank is long-term and is built from referrals, completed tasks, learning progress and consistency.</p><div id="progressArea"><div class="notice">Loading progress…</div></div></div>`}
async function loadProgress(){const el=document.getElementById('progressArea');if(!el)return;try{const [p,l]=await Promise.all([api('/progress'),api('/leaderboard')]);const rankPct=p.rank_progress??0;el.innerHTML=`<div class="grid"><div class="card"><div class="muted">Academy rank</div><div class="big">${escapeHtml(p.rank)}</div><div class="progress-track"><div class="progress-fill" style="width:${rankPct}%"></div></div><p class="muted">${p.next_rank?rankPct+'% toward '+escapeHtml(p.next_rank):'Top rank reached'}</p></div><div class="card"><div class="muted">XP</div><div class="big">${p.xp}</div><p class="muted">Permanent lifetime progress</p></div><div class="card"><div class="muted">Overall progress</div><div class="big">${p.overall_progress}%</div><p class="muted">Learning + tasks + referrals + consistency</p></div><div class="card"><div class="muted">Learning streak</div><div class="big">${p.streak} days</div><p class="muted">Keep building your routine</p></div></div><div class="grid3" style="margin-top:18px"><div class="card"><h3>Learning</h3><div class="big">${p.learning_progress}%</div><p class="muted">${p.completed_lessons}/${p.total_lessons} lessons</p></div><div class="card"><h3>Tasks</h3><div class="big">${p.tasks_progress}%</div><p class="muted">${p.completed_tasks}/${p.total_tasks} tasks</p></div><div class="card"><h3>Referrals</h3><div class="big">${p.qualified_referrals_lifetime}</div><p class="muted">Qualified referrals lifetime</p></div></div><div class="card" style="margin-top:18px"><h2>Long-term learning path</h2><p class="muted">Advancement is intentionally slow. The stage ladder is designed for a multi-year academy, not a six-month finish.</p><div class="rank-ladder">${['Beginner I','Beginner II','Beginner III','Beginner IV','Beginner V','Amateur I','Amateur II','Amateur III','Amateur IV','Amateur V','Professional I','Professional II','Professional III','Professional IV','Professional V','Expert I','Expert II','Expert III','Expert IV','Expert V','Master I','Master II','Master III','Master IV','Master V','Pips Master'].map(n=>`<span class="pill ${n===p.rank?'rank-current':''}">${n}</span>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Lessons</h2><div class="item-list">${(p.lessons||[]).map(i=>`<div class="statline"><span>${escapeHtml(i.course)} — ${escapeHtml(i.title)} <small class="muted">+${i.xp} XP</small></span><button class="btn alt" onclick="completeItem('lesson','${i.id}')">Complete</button></div>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Tasks</h2><div class="item-list">${(p.tasks||[]).map(i=>`<div class="statline"><span>${escapeHtml(i.title)} <small class="muted">+${i.xp} XP</small></span><button class="btn alt" onclick="completeItem('task','${i.id}')">Complete</button></div>`).join('')}</div></div><div class="card" style="margin-top:18px"><h2>Academy leaderboard</h2>${(l.leaderboard||[]).slice(0,10).map(i=>`<div class="statline"><span>#${i.rank} ${escapeHtml(i.username)} — ${escapeHtml(i.academy_rank)}</span><b>${i.xp} XP</b></div>`).join('')}</div>`}catch(e){el.innerHTML='<div class="notice">Progress could not be loaded from the backend yet. Connect the deployed API and try again.</div>'}}
async function completeItem(type,id){try{await api('/progress/'+type,{method:'POST',body:JSON.stringify({item_id:id})});toast('Progress saved');loadProgress()}catch(e){toast(e?.message||'Could not save progress')}}
function referrals(){const end=new Date(Date.UTC(new Date().getUTCFullYear(),new Date().getUTCMonth()+1,1));return `<div class="section"><h1 class="section-title">Monthly Referral Challenge</h1><p class="lead">Qualified referrals count toward the monthly challenge. The current month is shown below and the challenge resets automatically each month.</p><div class="ref-podium" id="refPodium"><div class="card podium-second"><div class="podium-medal">🥈</div><h2>2nd Place</h2><div class="big">80</div><div class="muted">qualified referrals</div><strong>$5</strong></div><div class="card podium-first"><div class="podium-medal">🥇</div><h2>1st Place</h2><div class="big">100</div><div class="muted">qualified referrals</div><strong>$10</strong></div><div class="card podium-third"><div class="podium-medal">🥉</div><h2>3rd Place</h2><div class="big">60</div><div class="muted">qualified referrals</div><strong>$3</strong></div></div><div class="card" style="margin-top:18px"><div class="grid3"><div><div class="muted">Your qualified this month</div><div class="big" id="myMonthRefs">—</div></div><div><div class="muted">Pending</div><div class="big" id="myPendingRefs">—</div></div><div><div class="muted">Your position</div><div class="big" id="myRefPosition">—</div></div></div><p class="muted">Pending referrals are recorded immediately. They normally qualify after about 48 hours plus basic account activity; referrals created before month-end can finish that qualification window afterward.</p></div><div class="card" style="margin-top:18px"><h2>Live leaderboard</h2><div id="refLeaderboard"><div class="notice">Loading…</div></div></div><div class="card" style="margin-top:18px"><h2>Anti-fake referral rules</h2><p class="muted">Only genuine, verified and active accounts count as qualified referrals. Duplicate or manipulative accounts can be flagged and removed from the competition. Shared devices or Wi-Fi alone are not treated as automatic proof of cheating.</p></div></div>`}
async function loadReferrals(){try{const x=await api('/referrals');document.getElementById('myMonthRefs').textContent=x.month_qualified??0;document.getElementById('myPendingRefs').textContent=x.pending??0;document.getElementById('myRefPosition').textContent=x.position?('#'+x.position):'—';const rows=x.monthly_leaderboard||[];const podium=[rows.find(r=>r.rank===2),rows.find(r=>r.rank===1),rows.find(r=>r.rank===3)];['podium-second','podium-first','podium-third'].forEach((cls,i)=>{const card=document.querySelector('.'+cls);const r=podium[i];if(card&&r){card.querySelector('h2').textContent=(i===0?'2nd':i===1?'1st':'3rd')+' Place — '+r.username;card.querySelector('.big').textContent=r.qualified;card.querySelector('.muted').textContent='qualified referrals';card.querySelector('strong').textContent=i===1?'$10':i===0?'$5':'$3'}});document.getElementById('refLeaderboard').innerHTML=rows.map(r=>`<div class="statline"><span>#${r.rank} ${escapeHtml(r.username)}</span><b>${r.qualified}</b></div>`).join('')||'<p class="muted">No qualified referrals recorded yet this month.</p>'}catch(e){document.getElementById('refLeaderboard').innerHTML='<div class="notice">Referral data could not be loaded from the backend.</div>'}}
function community(){return `<div class="section"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><div><h1 class="section-title">Community</h1><p class="muted">Share questions, lessons, market ideas and media with the group.</p></div><span id="lockState" class="lock">🔓 Open</span></div><div id="messages" class="msgbox"></div><div class="filters"><input id="msgInput" class="search" placeholder="Write a message..."><label class="file-btn">📷 Photo / 🎥 Video<input id="mediaInput" type="file" accept="image/*,video/*" class="hidden" onchange="previewMessageMedia(event)"></label><button class="btn" onclick="sendMsg()">Send</button></div><div id="mediaPreview" class="media-preview"></div><p class="muted" style="font-size:12px">You can attach one photo or video. Local mode keeps it on this browser; connected backend mode can store it when the API supports media.</p></div></div>`}
async function loadMessages(){try{const x=await api('/community/messages');renderMessages(x.messages||[]);lockState.textContent=x.locked?'🔒 Locked':'🔓 Open'}catch{const local=JSON.parse(localStorage.getItem('PMA_MESSAGES')||'[]');renderMessages(local);lockState.textContent='🔓 Local mode'}}
function renderMessages(list){messages.innerHTML=list.map(m=>`<div class="msg ${m.username===state.user.username?'right':''}"><b>${escapeHtml(m.username||'Member')}</b> <span class="muted">${escapeHtml(m.pma_id||'')}</span><br>${escapeHtml(m.text||'')}${m.media_data?(m.media_type||'').startsWith('video')?`<video class="message-media" controls src="${m.media_data}"></video>`:`<img class="message-media" src="${m.media_data}" alt="Shared media">`:''}<small class="muted"> ${escapeHtml(m.time||'just now')}</small></div>`).join('')||'<p class="muted">No messages yet.</p>'}
function previewMessageMedia(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Media must be under 5MB');e.target.value='';return}const r=new FileReader();r.onload=()=>{state.pendingMedia={data:r.result,type:file.type,name:file.name};mediaPreview.innerHTML=file.type.startsWith('video')?`<video controls src="${r.result}"></video>`:`<img src="${r.result}" alt="Selected media">`;};r.readAsDataURL(file)}
async function sendMsg(){const text=msgInput.value.trim();const media=state.pendingMedia;if(!text&&!media)return;const payload={text,media_data:media?.data||'',media_type:media?.type||''};try{await api('/community/messages',{method:'POST',body:JSON.stringify(payload)});addNotification('Community message sent','Your message was posted.');}catch{const arr=JSON.parse(localStorage.getItem('PMA_MESSAGES')||'[]');arr.push({username:state.user.username,pma_id:state.user.pma_id,text,media_data:payload.media_data,media_type:payload.media_type,time:new Date().toLocaleTimeString()});localStorage.setItem('PMA_MESSAGES',JSON.stringify(arr));renderMessages(arr);addNotification('Community message saved','Your message is saved locally on this browser.')}msgInput.value='';state.pendingMedia=null;mediaPreview.innerHTML='';if(window.loadMessages)loadMessages()}
function escapeHtml(s){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function profile(){const u=state.user;const pic=u.profile_picture||'assets/images/profile-placeholder.svg';const link=location.origin+location.pathname+'?ref='+encodeURIComponent(u.referral_code||'');return `<div class="section"><h1 class="section-title">My Profile</h1><p class="lead">Your profile changes are saved immediately on this browser and synced to your account when the backend is available. Reloading the page will keep your saved details and position.</p><div class="profile-layout"><div class="card profile-photo-card"><img id="profileAvatar" class="avatar" src="${pic}" alt="Profile picture"><div class="profile-actions"><label class="btn alt" style="cursor:pointer">Change picture<input id="picInput" type="file" accept="image/*" class="hidden" onchange="previewPicture(event)"></label><button class="btn ghost" onclick="removePicture()">Remove</button></div><p class="muted" style="font-size:12px">Changes are saved immediately in this browser.</p></div><div class="card"><h2>Personal details</h2><div class="profile-form"><div class="field"><label>Full Name</label><input id="pfName" value="${escapeAttr(u.full_name||'')}"></div><div class="field"><label>Username</label><input id="pfUser" value="${escapeAttr(u.username||'')}"></div><div class="field"><label>Phone Number</label><input id="pfPhone" value="${escapeAttr(u.phone||'')}" placeholder="Optional"></div><div class="field"><label>Date of Birth</label><input id="pfDob" type="date" value="${escapeAttr(u.dob||'')}"></div><div class="field full"><label>Email</label><input class="readonly" value="${escapeAttr(u.email||'')}" readonly></div><div class="field"><label>PMA User ID</label><input class="readonly" value="${escapeAttr(u.pma_id||'')}" readonly></div><div class="field"><label>IP Address</label><input class="readonly" value="System managed" readonly></div></div><button class="btn" onclick="saveProfile()">Save profile</button><div class="divider"></div><h3>Change password</h3><div class="profile-form"><div class="field"><label>New Password</label><div class="password-wrap"><input id="newPass" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass',this)">👁️</button></div></div><div class="field"><label>Confirm New Password</label><div class="password-wrap"><input id="newPass2" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass2',this)">👁️</button></div></div></div><button class="btn alt" onclick="changePassword()">Update password</button></div></div><div class="grid3" style="margin-top:18px"><div class="card color-card"><h3>Your referral code</h3><div class="big">${escapeHtml(u.referral_code||'')}</div><p class="muted">Share this link with someone you want to invite.</p><div class="copy-row"><input class="search" value="${escapeAttr(link)}" readonly id="refLink"><button class="btn alt" onclick="copyReferral(document.getElementById('refLink').value)">Copy referral link</button></div><div class="save-state">Your referral link is unique to your PMA account.</div></div><div class="card color-card"><h3>Editable</h3><p class="muted">Name, username, phone, date of birth and profile picture.</p></div><div class="card color-card"><h3>Protected</h3><p class="muted">PMA User ID and system-managed security information.</p></div></div></div>`}
function escapeAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
async function persistProfile(){try{if(!localStorage.getItem('PMA_TOKEN'))return false;const x=await api('/auth/profile',{method:'PUT',body:JSON.stringify({full_name:state.user.full_name,username:state.user.username,phone:state.user.phone,dob:state.user.dob,profile_picture:state.user.profile_picture||''})});if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);return true}}catch(e){}return false}
function previewPicture(e){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Please choose an image under 2MB');return}const r=new FileReader();r.onload=async()=>{state.user.profile_picture=r.result;saveLocalUser(state.user);const avatar=document.getElementById('profileAvatar');if(avatar)avatar.src=r.result;const saved=await persistProfile();addNotification('Profile picture updated',saved?'Your new profile picture was saved to your account.':'Your new profile picture was saved on this browser.','account');toast(saved?'Profile picture saved':'Profile picture saved locally')};r.readAsDataURL(file)}
async function removePicture(){state.user.profile_picture='';saveLocalUser(state.user);const saved=await persistProfile();page('profile');addNotification('Profile picture removed',saved?'Your profile picture was removed from your account.':'Your profile picture was removed on this browser.','account');toast('Profile picture removed')}
async function saveProfile(){state.user.full_name=pfName.value.trim();state.user.username=pfUser.value.trim();state.user.phone=pfPhone.value.trim();state.user.dob=pfDob.value;saveLocalUser(state.user);const saved=await persistProfile();userMini.textContent='@'+state.user.username;addNotification('Profile saved',saved?'Your profile details were saved to your account.':'Your profile details were saved on this browser.','account');toast(saved?'Profile saved successfully':'Profile saved locally');const pos=document.getElementById('screen')?.scrollTop||0;page('profile',false);requestAnimationFrame(()=>{document.getElementById('screen').scrollTop=pos})}
async function changePassword(){if(newPass.value.length<8){toast('Password must be at least 8 characters');return}if(newPass.value!==newPass2.value){toast('Passwords do not match');return}try{await api('/auth/password',{method:'PUT',body:JSON.stringify({password:newPass.value})});toast('Password changed successfully');addNotification('Password updated','Your password was updated successfully.','security')}catch(e){toast('Password could not be saved to the account.')}newPass.value='';newPass2.value=''}
async function copyText(t){return copyReferral(t)}
async function copyReferral(t){let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(String(t));ok=true}}catch(e){}if(!ok){const ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();try{ok=document.execCommand('copy')}catch(e){}ta.remove()}if(ok){toast('Referral link copied');addNotification('Referral link copied','Your referral link is ready to share.','referral')}else{const input=document.getElementById('refLink');if(input){input.focus();input.select()}toast('Copy failed — the link is selected for you')}}
function about(){const reviews=[['Amina Yusuf','https://randomuser.me/api/portraits/women/44.jpg','5.0','The layout makes the learning process feel much more organised. I can move from market education to analysis and then to the calculator without feeling lost.','5'],['Daniel Okoro','https://randomuser.me/api/portraits/men/32.jpg','4.8','I like how the academy brings several useful ideas together. The explanations are short enough to understand while still giving me a clear direction for what to study next.','5'],['Grace Mensah','https://randomuser.me/api/portraits/women/68.jpg','4.7','The community section gives the platform a more active feel, and having profile controls and referral tools in one place makes the experience easier to manage.','5'],['Samuel Adeyemi','https://randomuser.me/api/portraits/men/46.jpg','4.5','The design feels modern and the market sections are easy to move through. I especially like the focus on preparation, risk and understanding the market instead of chasing random entries.','4'],['Chiamaka Eze','https://randomuser.me/api/portraits/women/65.jpg','4.2','There is a lot to explore, but the sections are clearly separated. The academy feels like a useful place to keep learning notes, market ideas and community discussions together.','4'],['David Mensah','https://randomuser.me/api/portraits/men/75.jpg','4.6','The workspace is easy to move through and the market tools are presented in a way that keeps the important information visible.','5'],['Sarah Bello','https://randomuser.me/api/portraits/women/49.jpg','4.4','I like the balance between the academy material, account tools and community area. It feels much more like one complete workspace.','4']];return `<div class="section"><h1 class="section-title">About Pips Master Academy</h1><p class="lead">Pips Master Academy is built around a simple idea: make market learning, analysis, planning and community interaction easier to access from one organised workspace. The platform is designed to keep the learning process practical, visually clear and focused on building better habits over time.</p><div class="grid3"><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=85"><h3>Market structure</h3><p class="muted">Study trend direction, support and resistance, supply and demand, momentum and candle confirmation as connected parts of a bigger picture.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=1200&q=85"><h3>Analysis with context</h3><p class="muted">Instead of relying on one candle, compare multiple timeframes and look for structure before considering an opportunity.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85"><h3>Risk awareness</h3><p class="muted">A setup is only one part of a trading plan. Position size, stop placement and discipline matter too.</p></div></div><div class="card" style="margin-top:18px"><h2>Forex in a few words</h2><p class="lead">Forex is the market where currencies are traded in pairs, such as EUR/USD or GBP/JPY. Traders compare the strength of one currency against another and may study trends, market structure, economic news, support and resistance, and risk before making a decision. Prices can move quickly, so learning and risk control are important.</p></div><div class="card" style="margin-top:18px"><h2>Contact Us</h2><p class="muted">Need help with your account, profile, referral link or community access? Contact Pips Master Academy customer service directly on Telegram.</p><a class="btn" href="https://t.me/Zinolee6" target="_blank" rel="noopener">💬 Telegram Customer Service</a></div><div class="card photo-section" style="margin-top:18px"><h2>Inside the learning workspace</h2><p class="muted">Different visual scenes keep the academy from feeling like one repeated green-and-black pattern.</p><div class="image-band"><img src="https://images.unsplash.com/photo-1518186285589-2f7649de83e0?auto=format&fit=crop&w=900&q=85" alt="Market research workspace"><img src="https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=85" alt="Data dashboard"><img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=85" alt="Analytics screen"><img src="https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=900&q=85" alt="Modern workspace"></div></div><div class="card" style="margin-top:18px"><h2>Member Reviews</h2><p class="muted">Sample design testimonials — not verified current-member statements.</p><div class="rating-bars"><div class="rating-line"><span>5 ★</span><div class="rating-track"><div class="rating-fill fill5"></div></div><b>72%</b></div><div class="rating-line"><span>4 ★</span><div class="rating-track"><div class="rating-fill fill4"></div></div><b>18%</b></div><div class="rating-line"><span>3 ★</span><div class="rating-track"><div class="rating-fill fill3"></div></div><b>6%</b></div><div class="rating-line"><span>2 ★</span><div class="rating-track"><div class="rating-fill fill2"></div></div><b>3%</b></div><div class="rating-line"><span>1 ★</span><div class="rating-track"><div class="rating-fill fill1"></div></div><b>1%</b></div></div></div><div class="review-grid">${reviews.map(r=>`<article class="card review-card color-card"><div class="review-head"><img class="review-avatar" src="${r[1]}" alt="${r[0]}"><div><strong>${r[0]}</strong><div class="star">★★★★★ <span class="rating-number">${r[2]}</span></div></div></div><p class="quote">“${r[3]}”</p><p class="muted" style="font-size:12px">Sample testimonial • ${r[4]} star rating highlighted</p></article>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Questions & Answers</h2><p><b>Are signals guaranteed?</b><br><span class="muted">No. Market conditions change and any automated setup estimate depends on the quality and availability of connected data.</span></p><p><b>Can I edit my profile?</b><br><span class="muted">Yes. Personal details and your profile picture can be changed and saved.</span></p><p><b>How do I contact support?</b><br><span class="muted">Use the Telegram Customer Service button above.</span></p></div><div class="footer-note">Pips Master Academy • Learn first. Analyse clearly. Manage risk responsibly.</div></div>`}
function admin(){return `<div class="section"><h1 class="section-title">Admin Dashboard</h1><p class="lead">Server-authorised administrator controls and academy overview.</p><div id="adminStats" class="grid"><div class="notice">Loading admin stats…</div></div><div class="card" style="margin-top:18px"><h2>Admin profile</h2><p class="muted">Edit administrator details from My Profile. The protected PMA ID remains unchanged.</p><button class="btn" onclick="page('profile')">Edit my profile</button> <button class="btn alt" onclick="toggleLock()">Lock / Unlock Community</button></div></div>`}
async function toggleLock(){try{const x=await api('/admin/community/toggle',{method:'POST'});toast(x.locked?'Community locked':'Community opened');loadAdminStats()}catch(e){toast(e?.message||'Admin access required')}}
async function loadAdminStats(){const el=document.getElementById('adminStats');if(!el)return;try{const x=await api('/admin/stats');el.innerHTML=`<div class="card"><div class="muted">Total users</div><div class="big">${x.total_users}</div></div><div class="card"><div class="muted">Active in 7 days</div><div class="big">${x.active_7d}</div></div><div class="card"><div class="muted">Qualified referrals</div><div class="big">${x.qualified_referrals}</div></div><div class="card"><div class="muted">Community</div><div class="big">${x.community_locked?'🔒 Locked':'🔓 Open'}</div></div>`}catch(e){el.innerHTML='<div class="notice">Admin statistics are unavailable. Make sure you are signed in as the server-authorised admin.</div>'}}
async function syncBackendProfile(){if(!localStorage.getItem('PMA_TOKEN'))return;try{const x=await api('/auth/profile');if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);userMini.textContent='@'+state.user.username}}catch(e){}}
async function syncBackendNotifications(){try{const x=await api('/notifications');if(x.notifications?.length){const local=getNotifications();const ids=new Set(local.map(n=>String(n.server_id||'')));x.notifications.forEach(n=>{if(!ids.has(String(n.id))){local.unshift({...n,server_id:n.id})}});localStorage.setItem('PMA_NOTIFICATIONS',JSON.stringify(local.slice(0,60)));updateNotifBadge()}}catch(e){}}
function toggleNotifications(){const panel=document.getElementById('notifPanel');const arr=getNotifications();panel.classList.toggle('hidden');panel.innerHTML='<h3 style="margin-top:0">Notifications</h3>'+((arr.length)?arr.map(n=>`<div class="notification-item ${n.read?'':'unread'}"><b>${escapeHtml(n.title)}</b><p style="margin:5px 0" class="muted">${escapeHtml(n.text)}</p><small class="muted">${escapeHtml(n.time)}</small></div>`).join(''):'<div class="notice">No notifications yet.</div>')+'<button class="btn alt" onclick="markNotificationsRead();toggleNotifications()">Mark all as read</button>'}
async function markNotificationsRead(){const arr=getNotifications().map(n=>({...n,read:true}));localStorage.setItem('PMA_NOTIFICATIONS',JSON.stringify(arr));updateNotifBadge();try{await api('/notifications/read',{method:'POST'})}catch(e){}}
function startNotificationPolling(){clearInterval(state.notifTimer);state.notifTimer=setInterval(()=>{if(state.user)syncBackendNotifications()},30000)}
function toast(msg){toastEl.textContent=msg;toastEl.classList.remove('hidden');clearTimeout(window.tt);window.tt=setTimeout(()=>toastEl.classList.add('hidden'),2600)}
const toastEl=document.getElementById('toast');
function logout(){if(confirm('Do you really want to log out?')){api('/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('PMA_TOKEN');state.user=null;addNotification('Signed out','You logged out successfully.');show('welcome')}}
const local=loadLocalUser();if(local){state.user=local}state.notif=getNotifications();updateNotifBadge();if(state.user){show('app');adminNav.classList.toggle('hidden',state.user?.role!=='admin');userMini.textContent='@'+state.user.username;page(state.page||'home',true);syncBackendNotifications();syncBackendProfile();startNotificationPolling()}else if(state.ref){show('signup')}else{show('welcome')}window.addEventListener('beforeunload',()=>{const sc=document.getElementById('screen');if(state.user){localStorage.setItem('PMA_CURRENT_PAGE',state.page);localStorage.setItem('PMA_SCROLL_'+state.page,String(sc?.scrollTop||0));localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol)}});
